questions.solution:
function choose(n, k) {
  if (k < 0 || k > n) return 0;
  let result = 1;
  for (let i = 1; i <= k; i++) {
    result = result * (n - k + i) / i;
  }
  return result;
}

console.log(choose(8, 3));
console.log(choose(6, 2));
console.log(choose(5, 0), choose(5, 5), choose(3, 5));

